use hs_loop::dshgoal::{GoalSession,Authority};use serde_json::json;
#[test]fn cas_authority_and_disarmed_replay(){let mut s=GoalSession::default();assert!(s.call("create_goal",&json!({"objective":"fix"}),Authority::External).is_err());let g=s.call("create_goal",&json!({"objective":" fix ","max_goal_rounds":4}),Authority::HumanRoot).unwrap();assert_eq!(g["goal"]["objective"],"fix");assert_eq!(g["activation"],"armed");let id=g["goal"]["id"].as_str().unwrap();let update=json!({"goal_id":id,"revision":1,"action":"pause"});assert!(s.call("update_goal",&update,Authority::External).is_err());assert!(s.call("update_goal",&json!({"goal_id":id,"revision":2,"action":"pause"}),Authority::HumanRoot).is_err());let mut r=GoalSession::restore(s.snapshot()).unwrap();assert_eq!(r.view()["activation"],"disarmed");r.call("update_goal",&json!({"goal_id":id,"revision":1,"action":"resume"}),Authority::HumanRoot).unwrap();assert_eq!(r.view()["goal"]["revision"],2);assert_eq!(r.view()["activation"],"armed");s.call("update_goal",&update,Authority::HumanRoot).unwrap();assert!(s.call("update_goal",&json!({"goal_id":id,"revision":2,"action":"resume"}),Authority::HumanRoot).is_err());}
#[test]fn round_identity_threshold_and_budget(){let mut s=GoalSession::default();let g=s.call("create_goal",&json!({"objective":"work","max_goal_rounds":3}),Authority::HumanRoot).unwrap();let id=g["goal"]["id"].as_str().unwrap().to_owned();assert_eq!(s.admit_round().unwrap().unwrap()["round"],1);let upd=json!({"goal_id":id,"revision":1,"action":"blocked","blocked_reason":"missing input"});assert!(s.call("update_goal",&upd,Authority::GoalRound{id:"forged".into(),revision:1,round:1}).is_err());assert!(s.call("update_goal",&upd,Authority::GoalRound{id:id.clone(),revision:1,round:1}).is_err());s.admit_round().unwrap();s.admit_round().unwrap();s.call("update_goal",&upd,Authority::GoalRound{id:id.clone(),revision:1,round:3}).unwrap();assert_eq!(s.view()["goal"]["blockedReason"]["code"],"model-reported");assert!(s.admit_round().unwrap().is_none());assert!(s.call("update_goal",&json!({"goal_id":id,"revision":2,"action":"resume"}),Authority::HumanRoot).is_err());}
#[test]fn invalid_updates_do_not_mutate_and_terminal_not_checker_pass(){let mut s=GoalSession::default();for a in [json!({"objective":" "}),json!({"objective":"x","max_goal_rounds":1.5}),json!({"objective":"x","max_goal_rounds":0})]{assert!(s.call("create_goal",&a,Authority::HumanRoot).is_err());}let g=s.call("create_goal",&json!({"objective":"x"}),Authority::HumanRoot).unwrap();let id=g["goal"]["id"].clone();for a in [json!({"goal_id":id,"revision":1,"action":"edit"}),json!({"goal_id":id,"revision":1,"action":"pause","objective":"y"}),json!({"goal_id":id,"revision":1,"action":"complete","blocked_reason":"bad"})]{assert!(s.call("update_goal",&a,Authority::HumanRoot).is_err());assert_eq!(s.view(),g);}let complete=s.call("update_goal",&json!({"goal_id":id,"revision":1,"action":"complete"}),Authority::HumanRoot).unwrap();assert_eq!(complete["goal"]["phase"],"complete");assert!(complete.get("passed").is_none());assert!(s.admit_round().unwrap().is_none());assert!(s.call("create_goal",&json!({"objective":"next"}),Authority::HumanRoot).is_ok());}
#[test]fn round_limit_blocks_and_corrupt_replay_fails_closed(){let mut s=GoalSession::default();s.call("create_goal",&json!({"objective":"work","max_goal_rounds":1}),Authority::HumanRoot).unwrap();s.admit_round().unwrap();assert!(s.admit_round().unwrap().is_none());assert_eq!(s.view()["goal"]["phase"],"blocked");assert_eq!(s.view()["goal"]["blockedReason"]["code"],"round-limit");assert_eq!(s.view()["goal"]["revision"],2);let mut bad=s.snapshot();bad["blockedReason"]["extra"]=json!("forged");assert!(GoalSession::restore(bad).is_err());let mut bad=s.snapshot();bad["roundsStarted"]=json!(9007199254740992u64);assert!(GoalSession::restore(bad).is_err());}
#[test]fn source_claims_in_arguments_never_create_human_authority(){let mut s=GoalSession::default();for a in [json!({"objective":"x","source":"human"}),json!({"objective":"x","authority":"HumanRoot"}),json!({"objective":"x","root":true})]{assert!(s.call("create_goal",&a,Authority::External).is_err());assert_eq!(s.view(),json!({"goal":null}));}}
#[test]fn terminal_round_wrapup_is_not_pass_and_disarm_stops_driver(){let mut s=GoalSession::default();let g=s.call("create_goal",&json!({"objective":"work"}),Authority::HumanRoot).unwrap();let id=g["goal"]["id"].as_str().unwrap().to_owned();s.admit_round().unwrap();let a=Authority::GoalRound{id:id.clone(),revision:1,round:1};s.call("update_goal",&json!({"goal_id":id,"revision":1,"action":"complete"}),a.clone()).unwrap();assert!(s.wrapup(&a).unwrap().contains("not a checker pass"));assert!(s.wrapup(&Authority::HumanRoot).is_none());let mut r=GoalSession::default();r.call("create_goal",&json!({"objective":"work"}),Authority::HumanRoot).unwrap();r.disarm();assert!(r.admit_round().unwrap().is_none());}
#[test]fn fork_has_same_durable_goal_but_no_continuation_authority(){let mut s=GoalSession::default();s.call("create_goal",&json!({"objective":"parent"}),Authority::HumanRoot).unwrap();let mut fork=GoalSession::restore(s.snapshot()).unwrap();assert!(fork.admit_round().unwrap().is_none());assert_eq!(fork.snapshot(),s.snapshot());assert_eq!(s.view()["activation"],"armed");}
#[test]fn round_admission_replay_cannot_skip_or_change_source(){let mut s=GoalSession::default();let first=s.call("create_goal",&json!({"objective":"work"}),Authority::HumanRoot).unwrap();let a=json!({"operation":"create_goal","args":{"objective":"work"},"snapshot":first["goal"]});let src=s.admit_round().unwrap().unwrap();let b=json!({"operation":"round","source":src,"snapshot":s.snapshot()});assert!(GoalSession::fold(&[a.clone(),b.clone()]).is_ok());let mut bad=b.clone();bad["source"]["round"]=json!(2);assert!(GoalSession::fold(&[a.clone(),bad]).is_err());let mut bad=b;bad["snapshot"]["roundsStarted"]=json!(2);assert!(GoalSession::fold(&[a,bad]).is_err());}
#[test]fn host_goal_controls_resume_paused_without_model_permission(){let mut s=GoalSession::default();s.host_command("Work carefully").unwrap();s.host_command("pause").unwrap();let v=s.view();assert_eq!(v["goal"]["phase"],"paused");assert!(s.call("update_goal",&json!({"goal_id":v["goal"]["id"],"revision":v["goal"]["revision"],"action":"resume"}),Authority::HumanRoot).is_err());s.host_command("resume").unwrap();assert_eq!(s.view()["activation"],"armed");assert_eq!(s.view()["goal"]["revision"],3);s.host_command("edit Revised objective").unwrap();assert_eq!(s.view()["goal"]["objective"],"Revised objective");assert!(s.host_command("edit").is_err());s.host_command("clear").unwrap();assert_eq!(s.view(),json!({"goal":null}));}
#[test]fn replacing_completed_goal_replays_fresh_identity(){let mut s=GoalSession::default();s.host_command("first").unwrap();let first=s.snapshot();let v=s.view();let args=json!({"goal_id":v["goal"]["id"],"revision":1,"action":"complete"});s.call("update_goal",&args,Authority::HumanRoot).unwrap();let complete=s.snapshot();s.host_command("second").unwrap();let second=s.snapshot();let events=[json!({"operation":"host","input":"first","snapshot":first}),json!({"operation":"update_goal","args":args,"snapshot":complete}),json!({"operation":"host","input":"second","snapshot":second})];let replay=GoalSession::fold(&events).unwrap();assert_eq!(replay.snapshot(),s.snapshot());}
